css:
#top.hero-sticky {
  /* Desconta o header: ele é sticky e come altura de fluxo no topo, então um
     hero de 100vh começando abaixo dele termina embaixo da dobra — e a faixa
     que some é sempre a de baixo. --header-h é medida em JS.
     No celular a barra de endereço muda a altura da janela e o vh estoura;
     svh mede a janela pequena, que é a estável. */
  min-height: calc(100vh - var(--header-h, 0px));
  min-height: calc(100svh - var(--header-h, 0px));
  display: flex; flex-direction: column; justify-content: center;
  position: sticky; top: 0; z-index: 0;
  /* Iguais em cima e embaixo. Em vh para o conteúdo caber numa tela só: com
     valores fixos, uma janela baixa faz o texto transbordar. */
  padding-top: clamp(48px, 8vh, 120px);
  padding-bottom: clamp(48px, 8vh, 120px);
  padding-left: 60px; padding-right: 60px;
}

/* Como filho de um container flex, um `margin: 0 auto` encolhe o bloco até o
   tamanho do conteúdo e o centraliza — o que deixa o bloco no meio da tela
   com o texto alinhado à esquerda dentro dele. O width devolve a largura
   cheia: bloco na mesma margem do resto do site, texto à esquerda. */
#top.hero-sticky .hero-inner {
  width: 100%; max-width: 1360px; margin: 0 auto;
}

.page-flow {
  position: relative; z-index: 2;
  background: var(--bg);
}

.hero-badge {
  display: inline-flex; align-items: center; gap: 6px; padding: 9px 18px; margin-bottom: 24px;
  background: rgba(14,165,233,0.06); border: 1px solid var(--border-alt); border-radius: 100px;
  font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-muted);
}
.hero-badge span { color: var(--accent); font-weight: 700; }
.hero-title {
  font-family: 'Sora', sans-serif; font-weight: 700;
  font-size: clamp(34px, 5.5vw, 56px); letter-spacing: -0.03em; line-height: 1.05;
  margin-bottom: 28px; max-width: 800px;
}
.hero-desc { font-size: 16px; color: var(--text-muted); line-height: 1.6; max-width: 680px; }

.demo-secao {
  padding: 90px 60px; border-bottom: 1px solid var(--border);
  max-width: 1360px; margin: 0 auto;
}
.demo-eyebrow { font-size: 12px; color: var(--accent); letter-spacing: 0.2em; text-transform: uppercase; margin-bottom: 32px; }
.demo-heading { font-weight: 700; font-size: clamp(26px, 3.5vw, 40px); letter-spacing: -0.03em; }

js:
// O header é sticky e ocupa altura de fluxo no topo. Um hero com 100vh
// começando abaixo dele mede uma tela cheia, mas a última faixa cai embaixo
// da dobra — a simetria existe no CSS e não aparece no olho.
// Aqui a altura real do header vira uma custom property, e o hero desconta.
// É medida em vez de número fixo porque o header muda de altura no mobile.
export function initLayoutVars() {
  const header = document.querySelector('header');
  if (!header) return;

  function medir() {
    document.documentElement.style.setProperty(
      '--header-h',
      Math.round(header.getBoundingClientRect().height) + 'px'
    );
  }

  medir();
  if ('ResizeObserver' in window) new ResizeObserver(medir).observe(header);
  else window.addEventListener('resize', medir, { passive: true });
}
